#!/usr/bin/env bash
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
NAME="$(basename "$ROOT")"
SAFE="$(echo "$NAME" | tr '[:upper:]' '[:lower:]' | tr -c 'a-z0-9_-' '-' | sed 's/^-//;s/-$//')"
GITHUB_USER=mateuszzx
PARENT_ENV="$(cd "$ROOT/.." && pwd)/.env"
if [[ -f "$PARENT_ENV" ]]; then
  u="$(grep -E '^GITHUB_USER=' "$PARENT_ENV" | head -1 | cut -d= -f2- | tr -d '\r' || true)"
  [[ -n "$u" ]] && GITHUB_USER="$u"
fi
ZEPHYR_IMAGE_TAG="${ZEPHYR_IMAGE_TAG:-latest}"
cat > "$ROOT/.env" <<EOF
# Auto-generated by scripts/sync-compose-env.sh — do not commit
COMPOSE_PROJECT_NAME=${SAFE}
WORKSPACE_NAME=${NAME}
GITHUB_USER=${GITHUB_USER}
ZEPHYR_IMAGE_TAG=${ZEPHYR_IMAGE_TAG}
EOF
echo "project=${SAFE}  pull=ghcr.io/${GITHUB_USER}/zephyr-workspace:${ZEPHYR_IMAGE_TAG}  workspace=/home/dev/${NAME}"
